mapper.select:
SELECT id, project_id, actor_id, actor_name, action_type, object_type, object_id,
       object_code, before_json, after_json, request_id, ip_address, created_at
FROM em_audit_log

    AND project_id = #{projectId}
    AND action_type = #{actionType}

ORDER BY created_at DESC, id DESC
LIMIT #{limit}
